// Kirim seluruh daftar ke WAHA dengan interval + lapor balik tiap nomor ke app.
// CATATAN PENTING (sesuai backup ASF):
//  - Webhook v2 membungkus body POST di item.json.body
//  - Di Code node WAJIB pakai this.helpers.httpRequest (fetch TIDAK ada)
//  - $env butuh N8N_BLOCK_ENV_ACCESS_IN_NODE=false

const body = ($input.first().json.body) || $input.first().json;
const jobId = body.jobId;
const callbackUrl = body.callbackUrl;
const intervalMs = (Number(body.intervalSeconds) > 0 ? Number(body.intervalSeconds) : 7) * 1000;
const contacts = Array.isArray(body.contacts) ? body.contacts : [];

const base = ($env.N8N_WAHA_BASE_URL || 'http://waha:3000').replace(/\/+$/, '');
const apiKey = $env.N8N_WAHA_API_KEY || '';
const session = $env.N8N_WAHA_SESSION || 'default';

const results = [];

for (let i = 0; i < contacts.length; i++) {
  const c = contacts[i];
  let status = 'sent';
  let detail = '';

  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: base + '/api/sendText',
      headers: { 'X-Api-Key': apiKey, 'Content-Type': 'application/json' },
      body: { session, chatId: String(c.target) + '@c.us', text: c.message },
      json: true,
    });
  } catch (e) {
    status = 'failed';
    detail = String((e && e.message) ? e.message : e).slice(0, 200);
  }

  // Callback hasil per nomor ke aplikasi (status realtime di /blast)
  if (callbackUrl) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: callbackUrl,
        headers: { 'Content-Type': 'application/json' },
        body: { jobId, target: c.target, status, detail },
        json: true,
      });
    } catch (e) { /* abaikan kegagalan callback, lanjut */ }
  }

  results.push({ target: c.target, status, detail });

  // Interval antar pesan (lewati delay untuk pesan terakhir)
  if (i < contacts.length - 1) {
    await new Promise((r) => setTimeout(r, intervalMs));
  }
}

return [{ json: { jobId, total: contacts.length, results } }];
